package com.greatleyposhley.professy.collaboration;

import org.springframework.web.bind.annotation.*;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.http.HttpStatus;
import org.springframework.web.server.ResponseStatusException;
import tools.jackson.databind.ObjectMapper;
import java.util.*;
import static com.greatleyposhley.professy.collaboration.WorkAccess.number;

/** Agents are distinct workspace actors, never user accounts or inherited administrator identities. */
@RestController @RequestMapping("/api/workspace/agents")
public class WorkspaceAgents {
 private final WorkAccess access;private final ObjectMapper json;
 public WorkspaceAgents(WorkAccess access,ObjectMapper json){this.access=access;this.json=json;}
 private String text(Object value,int max){String text=Objects.toString(value,"").trim();if(text.length()>max)throw new IllegalArgumentException("Agent field is too long");return text;}
 public Map<String,Object> row(long id){var rows=access.jdbc.queryForList("SELECT a.id,a.display_name AS name,a.status,a.created_by AS ownerId,a.created_at AS createdAt,p.designation,p.description,p.instructions,p.model FROM workspace_actors a JOIN workspace_agent_profiles p ON p.actor_id=a.id WHERE a.org_id=? AND a.actor_type='AGENT' AND a.id=?",access.actor().getOrgId(),id);if(rows.isEmpty())throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Agent not found");return rows.getFirst();}
 public boolean manages(Map<String,Object> agent){return access.admin(access.actor())||number(agent.get("ownerId"))==access.actor().getId();}
 public List<Long> projects(long id){return access.jdbc.queryForList("SELECT project_id FROM workspace_agent_projects WHERE actor_id=? ORDER BY project_id",Long.class,id);}
 public Map<String,Object> view(Map<String,Object> agent){var result=new LinkedHashMap<>(agent);result.put("actorType","AGENT");result.put("selectionId",-number(agent.get("id")));result.put("projectIds",projects(number(agent.get("id"))));result.put("canManage",manages(agent)&&access.policy.can(access.actor(),"AGENTS.UPDATE"));result.put("providerConfigured",false);return result;}
 @GetMapping public Object list(@RequestParam(defaultValue="0")long projectId,@RequestParam(defaultValue="")String q){access.require("AGENTS.READ");if(projectId>0)access.project(projectId);String term="%"+q.toLowerCase(Locale.ROOT)+"%";return access.jdbc.queryForList("SELECT a.id,a.display_name AS name,a.status,a.created_by AS ownerId,a.created_at AS createdAt,p.designation,p.description,p.model FROM workspace_actors a JOIN workspace_agent_profiles p ON p.actor_id=a.id WHERE a.org_id=? AND a.actor_type='AGENT' AND LOWER(CONCAT(a.display_name,' ',p.designation)) LIKE ? AND (?=0 OR EXISTS(SELECT 1 FROM workspace_agent_projects ap WHERE ap.actor_id=a.id AND ap.project_id=?)) ORDER BY a.display_name LIMIT 500",access.actor().getOrgId(),term,projectId,projectId).stream().map(this::view).toList();}
 @GetMapping("/{id}")public Object get(@PathVariable long id){access.require("AGENTS.READ");return view(row(id));}
 @PostMapping @Transactional public Object create(@RequestBody Map<String,Object> body){access.require("AGENTS.CREATE");String name=text(body.get("name"),120);if(name.isBlank())throw new IllegalArgumentException("Give the agent a name");var actor=access.actor();access.jdbc.update("INSERT INTO workspace_actors(org_id,actor_type,display_name,status,created_by) VALUES(?,'AGENT',?,'ACTIVE',?)",actor.getOrgId(),name,actor.getId());long id=access.jdbc.queryForObject("SELECT LAST_INSERT_ID()",Long.class);access.jdbc.update("INSERT INTO workspace_agent_profiles(actor_id,designation,description,instructions,model) VALUES(?,?,?,?,?)",id,text(body.get("designation"),120),text(body.get("description"),4000),text(body.get("instructions"),20000),text(body.get("model"),120));memberships(id,body);access.policy.event(actor,"AGENT_UPDATED",0);return get(id);}
 @PutMapping("/{id}")@Transactional public Object update(@PathVariable long id,@RequestBody Map<String,Object> body){var agent=row(id);access.require("AGENTS.UPDATE");if(!manages(agent))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Only the agent owner or administrator can change its setup");String name=text(body.get("name"),120),status=text(body.get("status"),20);if(name.isBlank()||!Set.of("ACTIVE","PAUSED","ARCHIVED").contains(status))throw new IllegalArgumentException("Enter a name and valid agent status");access.jdbc.update("UPDATE workspace_actors SET display_name=?,status=? WHERE id=?",name,status,id);access.jdbc.update("UPDATE workspace_agent_profiles SET designation=?,description=?,instructions=?,model=? WHERE actor_id=?",text(body.get("designation"),120),text(body.get("description"),4000),text(body.get("instructions"),20000),text(body.get("model"),120),id);memberships(id,body);access.policy.event(access.actor(),"AGENT_UPDATED",0);return get(id);}
 private void memberships(long id,Map<String,Object> body){if(!(body.get("projectIds") instanceof List<?> ids))return;if(ids.size()>200)throw new IllegalArgumentException("Choose up to 200 projects");for(Object project:ids)access.project(number(project));var existing=projects(id);for(long project:existing)if(ids.stream().noneMatch(x->number(x)==project)&&access.jdbc.queryForObject("SELECT COUNT(*) FROM ticket_actor_assignments WHERE actor_id=? AND project_id=?",Integer.class,id,project)>0)throw new IllegalArgumentException("Reassign this agent's tickets before removing its project access");access.jdbc.update("DELETE FROM workspace_agent_projects WHERE actor_id=?",id);for(long project:ids.stream().mapToLong(WorkAccess::number).distinct().toArray())access.jdbc.update("INSERT INTO workspace_agent_projects(actor_id,project_id) VALUES(?,?)",id,project);}
 @GetMapping("/{id}/access")public Object permissions(@PathVariable long id){row(id);var roles=access.jdbc.queryForList("SELECT role_code FROM agent_workspace_roles WHERE actor_id=? ORDER BY role_code",String.class,id);var overrides=new LinkedHashMap<String,Boolean>();for(var entry:access.jdbc.queryForList("SELECT permission,allowed FROM agent_permission_overrides WHERE actor_id=?",id))overrides.put(entry.get("permission").toString(),Boolean.TRUE.equals(entry.get("allowed"))||number(entry.get("allowed"))==1);var grants=new HashSet<String>();for(var entry:access.jdbc.queryForList("SELECT r.permissions_json FROM workspace_roles r JOIN agent_workspace_roles a ON a.role_code=r.code AND r.org_id=? WHERE a.actor_id=?",access.actor().getOrgId(),id))for(Object p:json.readValue(entry.get("permissions_json").toString(),List.class))grants.add(p.toString());var effective=new LinkedHashMap<String,Boolean>();for(String p:WorkspacePolicy.permissions())effective.put(p,WorkspacePolicy.resolve(p,grants,overrides));return Map.of("roles",roles.isEmpty()?List.of("MEMBER"):roles,"overrides",overrides,"effective",effective,"superUser",false);}
 @PutMapping("/{id}/access")@Transactional public Object permissions(@PathVariable long id,@RequestBody Map<String,Object> body){access.requireAdmin();row(id);if(!(body.get("roles") instanceof List<?> roles)||!(body.get("overrides") instanceof Map<?,?> overrides))throw new IllegalArgumentException("Roles and overrides are required");var allowed=access.jdbc.queryForList("SELECT code FROM workspace_roles WHERE org_id=?",String.class,access.actor().getOrgId());if(!allowed.containsAll(roles)||!WorkspacePolicy.permissions().containsAll(overrides.keySet())||overrides.values().stream().anyMatch(x->!(x instanceof Boolean)))throw new IllegalArgumentException("Choose valid roles and permissions");access.jdbc.update("DELETE FROM agent_workspace_roles WHERE actor_id=?",id);for(Object role:new HashSet<>(roles))access.jdbc.update("INSERT INTO agent_workspace_roles(actor_id,role_code) VALUES(?,?)",id,role);access.jdbc.update("DELETE FROM agent_permission_overrides WHERE actor_id=?",id);for(var entry:overrides.entrySet())access.jdbc.update("INSERT INTO agent_permission_overrides(actor_id,permission,allowed) VALUES(?,?,?)",id,entry.getKey(),entry.getValue());access.policy.event(access.actor(),"AGENT_UPDATED",0);return permissions(id);}
 @GetMapping("/{id}/work")public Object work(@PathVariable long id){access.require("AGENTS.READ");row(id);var result=new ArrayList<Map<String,Object>>();for(var assignment:access.jdbc.queryForList("SELECT ticket_type AS kind,ticket_id AS id,project_id AS projectId,assignment_role AS role FROM ticket_actor_assignments WHERE org_id=? AND actor_id=? ORDER BY updated_at DESC LIMIT 500",access.actor().getOrgId(),id)){try{var ticket=access.ticket(assignment.get("kind").toString(),number(assignment.get("id")),false);assignment.put("title",Objects.toString(ticket.get("title"),Objects.toString(ticket.get("name"),"Untitled item")));assignment.put("status",Objects.toString(ticket.get("status"),"BACKLOG"));result.add(assignment);}catch(ResponseStatusException ignored){}}return result;}
 @PostMapping("/{id}/reply")public Object reply(@PathVariable long id,@RequestBody Map<String,Object> body){access.require("AGENTS.READ");var agent=row(id);if(!"ACTIVE".equals(agent.get("status")))throw new ResponseStatusException(HttpStatus.CONFLICT,"This agent is paused");if(text(body.get("message"),20000).isBlank())throw new IllegalArgumentException("Write a message");throw new ResponseStatusException(HttpStatus.SERVICE_UNAVAILABLE,"Agent provider is not configured. The administrator can connect a model provider later; no automated reply has been generated.");}
}
